import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`creator-media-kit`,heroTitle:`Build your media kit in minutes`,heroSubtitle:`Perplexity Computer turns your creator profile into a polished media kit with audience highlights, partnership packages, and brand-ready positioning.`,inputUrlCta:`Build my media kit`,inputUrlPlaceholder:`e.g. youtube.com/@yourchannel or instagram.com/yourhandle`,inputUrlPrefill:`Go to {url} and build a creator media kit. (1) Analyze the profile, audience, content themes, engagement patterns, and growth signals. (2) Summarize the strongest proof points a brand partner would care about. (3) Draft positioning that explains the audience fit, creator angle, and partnership value. (4) Create sponsorship package options with clear deliverables and suggested framing. (5) Deliver a polished media kit outline with stats, audience summary, package options, and partnership messaging that is ready to drop into a deck or doc.`,heroOverlaySteps:[`Reviewing your creator profile, audience signals, and strongest engagement proof points`,`Summarizing the audience story and what makes the brand fit credible`,`Packaging deliverables, positioning, and sponsorship options into a clean kit`,`Media kit with stats, audience highlights, and partnership packages ready to share`],generatingSteps:[`Inspecting {url} to understand the creator profile, audience quality, and content positioning`,`Designing an agent to pull the signals brands care about and turn them into a clear story`,`Configuring package options, deliverable framing, and partnership positioning for the kit`,`Packaging the work into a media kit outline that can move straight into a deck or doc`],featureSectionTitle:`From creator profile to partner-ready story`,featureCardTitles:[`Connects to your creator workflow`,`Outputs you can share with brands`],featureCardDescriptions:[`Computer breaks the work into profile analysis, audience framing, package design, and message polish so the media kit feels intentional instead of generic.`,`Docs, slides, Notion, Canva, and outreach workflows can stay connected so the media kit is easy to reuse across brand conversations.`,`Audience summary. Proof points. Partnership angles. Sponsorship packages. Brand-ready messaging. Computer delivers the materials you need to open the conversation.`],capabilitySectionTitle:`Your media kit builder, on demand`,capabilitySectionSubtitle:`Share your profile, step away, and come back to a polished creator story brands can understand quickly.`,capabilityCards:[{title:`Profile Analysis`,description:`Computer can review your creator profile and identify the audience, engagement, and positioning signals most relevant to brand partners.`},{title:`Audience Framing`,description:`Computer can turn follower and engagement patterns into a concise audience story that explains why your reach matters.`},{title:`Package Design`,description:`Computer can outline sponsorship packages and deliverables so brands understand the ways they can work with you.`},{title:`Connect Your Tools`,description:`Computer can move the kit into docs, slides, and creator workflows so it is easy to reuse in outreach and negotiations.`},{title:`Brand Positioning`,description:`Computer can draft the partnership angles and talking points that make the creator fit clear to potential sponsors.`},{title:`Kit Refresh`,description:`Computer can revisit the media kit later and refresh it as your audience, content mix, or brand goals evolve.`}]});export{t as default};
